# fastapi/responses.py:44-48  (fastapi.responses.ORJSONResponse.render)
class ORJSONResponse(JSONResponse):
    def render(self, content: Any) -> bytes:
        assert orjson is not None, "orjson must be installed to use ORJSONResponse"
        return orjson.dumps(
            content, option=orjson.OPT_NON_STR_KEYS | orjson.OPT_SERIALIZE_NUMPY
        )

# docs_src/custom_response/tutorial009c.py:12-14  (docs_src.custom_response.tutorial009c.CustomORJSONResponse.render)
class CustomORJSONResponse(Response):
    def render(self, content: Any) -> bytes:
        assert orjson is not None, "orjson must be installed"
        return orjson.dumps(content, option=orjson.OPT_INDENT_2)

# fastapi/responses.py:31-33  (fastapi.responses.UJSONResponse.render)
class UJSONResponse(JSONResponse):
    def render(self, content: Any) -> bytes:
        assert ujson is not None, "ujson must be installed to use UJSONResponse"
        return ujson.dumps(content, ensure_ascii=False).encode("utf-8")

